 					EndLine:   from.EndLine,
 					Detail:    call.Detail,
 				}},
 				WarningCodes: []string{},
 			})
 			break
 		}
 	}
 	for _, call := range chainedReturnCalls {
 		for _, typeName := range methodReturnChainTypes(from, call.TypeName, []string{call.FirstMethod}, methodsByContainer, symbolsByShortName, returnTypesBySymbolNameAndFile) {
 			sym, ok := firstTypeLikeNamed(sharedTypeCandidates(from, symbolsByShortName[typeName]), typeName)
 			if !ok {
 				continue
 			}
 			method, ok := methodsByContainer[sym.ID][call.Method]
 			if !ok || method.ID == from.ID {
 				continue
 			}
 			scope := "file"
 			if method.FilePath != from.FilePath {
 				scope = "module"
 			}
 			relations = append(relations, RelationRecord{
 				RecordType:    "relation",
 				FromID:        from.ID,
 				ToID:          method.ID,
 				Type:          "CALLS",
 				Confidence:    0.74,
 				Reason:        "method call resolved via chained constructor-return type",
 				RelationScope: scope,
 				Resolution:    "type_inferred",
 				TargetKind:    "symbol",
 				Evidence: []Evidence{{
 					Kind:      "call_site",
 					FilePath:  from.FilePath,
 					StartLine: from.StartLine,
 					EndLine:   from.EndLine,
 					Detail:    call.Detail,
 				}},
 				WarningCodes: []string{},
 			})
 			break
 		}
 	}
 	for _, call := range deepChainedReturnCalls {
 		if len(call.Methods) < 2 {
 			continue
 		}
 		intermediateMethods := call.Methods[:len(call.Methods)-1]
 		finalMethod := call.Methods[len(call.Methods)-1]
 		for _, typeName := range methodReturnChainTypes(from, call.TypeName, intermediateMethods, methodsByContainer, symbolsByShortName, returnTypesBySymbolNameAndFile) {
 			sym, ok := firstTypeLikeNamed(sharedTypeCandidates(from, symbolsByShortName[typeName]), typeName)
 			if !ok {
 				continue
 			}
 			method, ok := methodsByContainer[sym.ID][finalMethod]
 			if !ok || method.ID == from.ID {
 				continue
 			}
 			scope := "file"
 			if method.FilePath != from.FilePath {
 				scope = "module"
 			}
 			relations = append(relations, RelationRecord{
 				RecordType:    "relation",
 				FromID:        from.ID,
 				ToID:          method.ID,
 				Type:          "CALLS",
 				Confidence:    0.71,
 				Reason:        "method call resolved via deep chained constructor-return type",
 				RelationScope: scope,
 				Resolution:    "type_inferred",
 				TargetKind:    "symbol",
 				Evidence: []Evidence{{
 					Kind:      "call_site",
 					FilePath:  from.FilePath,
 					StartLine: from.StartLine,
