 				}
 				relations = append(relations, RelationRecord{
 					RecordType:    "relation",
 					FromID:        from.ID,
 					ToID:          method.ID,
 					Type:          "CALLS",
 					Confidence:    0.7,
 					Reason:        "method call resolved via deep chained returned receiver type",
 					RelationScope: scope,
 					Resolution:    "type_inferred",
 					TargetKind:    "symbol",
 					Evidence: []Evidence{{
 						Kind:      "call_site",
