 	if kubernetesManifestHasAnyKind(content, "PersistentVolumeClaim") {
 		for _, ref := range kubernetesNamedRefBlockReferences(content, "dataSource", "kubernetes_pvc_data_source_ref", 0.82, kubernetesExplicitReferenceKind) {
