 func splitKubernetesNamedList(value string) []string {
 	seen := map[string]bool{}
 	var out []string
 	for _, part := range strings.FieldsFunc(value, func(r rune) bool {
 		return r == ',' || r == ';' || r == '\n'
 	}) {
 		name := strings.Trim(strings.TrimSpace(part), `"'`)
 		if name == "" || seen[name] {
 			continue
 		}
 		seen[name] = true
 		out = append(out, name)
 	}
 	sort.Strings(out)
 	return out
 }

