func TestGPSSpecAndContextCommands(t *testing.T) {
	repo := t.TempDir()
	var out bytes.Buffer
	opts := Options{Version: "test", Env: EntireEnv{RepoRoot: repo}, Stdout: &out}
	if err := Run(t.Context(), opts, []string{"spec", "init", "--repo", repo}); err != nil {
